size_t CalculateSharedPrefix(const leveldb::Slice& a, const leveldb::Slice& b) {
    const size_t min_size = std::min(a.size(), b.size());
    size_t shared = 0;
    while (shared < min_size && a.data()[shared] == b.data()[shared]) {
        shared++;
    }
    return shared;
}

